class Solution { fun spellchecker(wordlist:Array<String>,queries:Array<String>):Array<String>{val exact=wordlist.toHashSet();val lower=mutableMapOf<String,String>();val vowel=mutableMapOf<String,String>();fun mask(word:String):String{return word.map{if(it in "aeiou")'*' else it}.joinToString("")};for(word in wordlist){val normalized=word.lowercase();lower.putIfAbsent(normalized,word);vowel.putIfAbsent(mask(normalized),word)};return Array(queries.size){i->val query=queries[i];val normalized=query.lowercase();when{query in exact->query;normalized in lower->lower[normalized]!!;else->vowel[mask(normalized)]?:""}}} }
